import{_ as e,c as p,o as r,af as i}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"50、【鼎】 巽下离上","description":"周易集注 - 50、【鼎】 巽下离上","frontmatter":{"title":"50、【鼎】 巽下离上","description":"周易集注 - 50、【鼎】 巽下离上"},"headers":[],"relativePath":"zh/classics/jizhu/054.md","filePath":"zh/classics/jizhu/054.md"}'),l={name:"zh/classics/jizhu/054.md"};function h(t,a,s,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_50、【鼎】-巽下离上" tabindex="-1">50、【鼎】 巽下离上 <a class="header-anchor" href="#_50、【鼎】-巽下离上" aria-label="Permalink to “50、【鼎】 巽下离上”">​</a></h1><p>鼎者，烹饪之器，其卦巽下离上，下阴为足，二三四阳为腹，五阴为耳，上阳为铉，鼎之象也。又以巽木入离火而致烹饪，鼎之用也。《序卦》：革物者，莫若鼎，故受之以鼎，所以次革。</p><p>彖辞，明观孔子《彖辞》“是以元亨”，则吉字当从《本义》，作衍文。</p><p>《彖》曰：鼎，象也，以木巽火，亨饪也。圣人亨以享上帝，而大亨以养圣贤，巽而耳目聪明，柔进而上行，得中而应乎刚，是以元亨。亨并庚反</p><p>以卦体释卦名，又以卦德卦综卦体释卦辞。象者，六爻有鼎之象也。巽者入也，以木入于火也。亨煮也，饪熟食也。亨饪有调和之义，故《论语》曰“失饪不食”。象者鼎之体，亨饪者鼎之用，所以名鼎。圣人者君也，圣贤者臣也。古人有圣德者，皆可称圣，如汤诰称伊尹为元圣是也。亨饪之事，不过祭祀宾客而已。祭祀之大者，无出于上帝，宾客之重者，无过于圣贤。享上帝贵质，故止曰亨。享圣贤贵丰，故曰大亨。所以享帝用特牲，而享圣贤以饔牲牢礼也。巽而耳目聪明者，内而此心巽顺，外而耳目聪明也。离为目，五为鼎耳，故曰耳目。皆有离明之德，故曰聪明。柔进而上行者，鼎综革，二卦同体，文王综为一卦，故《杂卦》曰“革去故也，鼎取新也”，言革下卦之离，进而为鼎之上卦也。进而上行，居五之中，应乎二之刚也。若以人事论，内巽外聪，有其德，进而上行，有其位，应乎刚有其辅，是以元亨。</p><h3 id="《象》曰-木上有火-鼎-君子以正位凝命。" tabindex="-1">《象》曰：木上有火，鼎，君子以正位凝命。 <a class="header-anchor" href="#《象》曰-木上有火-鼎-君子以正位凝命。" aria-label="Permalink to “《象》曰：木上有火，鼎，君子以正位凝命。”">​</a></h3><p>正对偏倚言，凝对散漫言。正位者，端庄安正之谓，即斋明盛服，非礼不动也。凝者成也、坚也，命者天之命也，凝命者，天命凝成坚固，国家安于磐石。所谓协乎上下，以承天休也。鼎譬之位，命譬之实。鼎之器正，然后可凝其所受之实。君之位正，然后可凝其所受之命。鼎综革，故革亦言命。孔子因大禹铸九鼎象物，成王定鼎于郏鄏，卜世三十，卜年七百，所以说到正位凝命上去。周烈王二十三年，九鼎震，此不能正位凝命之兆也，其后秦遂灭周，取九鼎。则鼎所系匪轻矣，故以鼎为宗庙之宝器。及天宝五年，宰臣李适之常列鼎爼，具膳羞，中夜，鼎跃相鬬不解，鼎耳及足皆折，岂以明皇不能正位凝命，而有幸蜀之祸与。</p><p>初六，鼎颠趾，利出否，得妾以其子，无咎。</p><p>巽错震，震为足，趾之象也。巽为长女，位卑居下，妾之象也。震为长子，子之象也。鼎为宝器，主器者莫若长子，则子之意，亦由鼎而来也。颠趾者，颠倒其趾也。凡洗鼎而出水，必颠倒其鼎，以鼎足反加于上，故曰颠趾。否者，鼎中之污秽也。利出否者，顺利其出否也，故孔子曰鼎取新也。得者获也，得妾者，买妾而获之也。以者因也，因其子而买妾也。言洗鼎之时，趾乃在下之物，不当加于其上。今颠于上，若悖上下之序矣。然颠趾者，非得已也，以其顺利于出否也。亦犹一夫一妇，人道之常，既有妻，岂可得妾?今得其妾，若失尊卑之分矣，然得妾者，不得已也，以其欲生子，而不得不买妾也。得妾以其子，又颠趾出否之象也。</p><p>初六居下，尚未烹饪，正洗鼎之时，颠趾以出否，故有得妾以其子之象。占者得此，凡事迹虽若悖其上下尊卑之序，于义则无咎也。</p><h3 id="《象》曰-鼎颠趾-未悖也。利出否-以从贵也。" tabindex="-1">《象》曰：鼎颠趾，未悖也。利出否，以从贵也。 <a class="header-anchor" href="#《象》曰-鼎颠趾-未悖也。利出否-以从贵也。" aria-label="Permalink to “《象》曰：鼎颠趾，未悖也。利出否，以从贵也。”">​</a></h3><p>未悖者，未悖于理也。言以颠趾于鼎之上，虽若颠倒其上下之序，然洗鼎当如此，未为悖理也。贵对贱，言鼎中之否，则贱物也。以从贵言，欲将珍羞贵重之物，相从以实于鼎中，不得不出其否贱，以濯洁也。</p><p>九二，鼎有实，我仇有疾，不我能即，吉。</p><p>鼎有实者，既洗鼎矣，乃实物于其中也。阳实阴虚，故言实。仇者，匹也，对也，指初也。疾者，阴柔之疾也。即者就也。言初虽有疾，九二则刚中自守，不能使我与之即就也。此九二之能事，非戒辞也。</p><p>九二以刚居中，能守其刚中之实德，虽比于初，而不轻于所与，有鼎有美实，我仇有疾，不我能即，而凂我实德之象。占者如此，则刚中之德不亏，其吉可知矣。</p><h3 id="《象》曰-鼎有实-慎所之也。我仇有疾-终无尤也。" tabindex="-1">《象》曰：鼎有实，慎所之也。我仇有疾*，终无尤也。 <a class="header-anchor" href="#《象》曰-鼎有实-慎所之也。我仇有疾-终无尤也。" aria-label="Permalink to “《象》曰：鼎有实，慎所之也。我仇有疾*，终无尤也。”">​</a></h3><p>慎所之者，慎所往也。此一句亦言九二之能事，非戒辞也，言九二有阳刚之实德，自能慎于所往，择善而交，不失身于阴党也。终无尤者，言我仇虽有疾，然慎于所往，不我能即，而不失身于彼，有何过尤哉。</p><ul><li>原文误作“我仇有吉”。</li></ul><p>九三，鼎耳革，其行塞。雉膏不食，方雨亏悔，终吉。</p><p>三变为离为坎，坎为耳，耳之象也。革者变也，坎为耳痛，耳革之象也。三未变，错震足为行，三变则成坎陷，不能行矣，行塞之象也。其行塞者，不能行也。离为雉，雉之象也。坎为膏，膏之象也。中爻兑，三变则不成兑口，不食之象也。三变则内坎水，外亦坎水，方雨之象也。鼎之所赖以举行者耳也，三居木之极，上应火之极，木火既极，则鼎中腾沸，并耳亦炽热革变，而不可举移矣，故其行塞也。雨者水也，亏者损也，悔者鼎不可举移，而雉膏之美味，不得其食，不免至于悔也。方雨亏悔者，言耳革不食，惟救之以水耳。方雨则能亏损其腾沸炽热之势，而悔者不至于悔矣。终吉者，鼎可移，美味可食也。</p><p>九三以阳刚居鼎腹之中，本有美实之德，但应与木火之极，烹饪太过，故有耳革行塞，雉膏不食之象。然阳刚得正，故又有方雨亏悔之象。占者如是，始虽若不利，终则吉也。</p><h3 id="《象》曰-鼎耳革-失其义也。" tabindex="-1">《象》曰：鼎耳革，失其义也。 <a class="header-anchor" href="#《象》曰-鼎耳革-失其义也。" aria-label="Permalink to “《象》曰：鼎耳革，失其义也。”">​</a></h3><p>义者宜也，鼎烹饪之木火不可过，不可不及，方得烹饪之宜。今木火太过，则失烹饪之宜矣，所以耳革也。</p><p>九四，鼎折足，覆公餗，其形渥，凶。</p><p>四变，中爻为震，足之象也。中爻兑，为毁折，折之象也。鼎实近鼎耳，实已满矣，令震动，覆之象也。餗者羹糁也，八珍之膳，鼎之实也。鼎以享帝养贤，非自私也，故曰公餗。渥者霑濡也，言覆其鼎，而鼎之上皆霑濡其羹糁也。以人事论，项羽之入咸阳，安禄山之陷长安，宗庙烧焚，宝器披离，不复见昔日彼都人士之盛，其形渥之象也。不可依晁氏“其刑剭凶”者，败国杀身也。若不以象论，以二体论，离巽二卦成鼎，下体巽有足而无耳，故曰耳革。上体离有耳而无足，故曰折足。</p><p>九四居大臣之位，任天下之重者。但我本不中不正，而又下应初六之阴柔，则委任亦非其人，不能胜大臣之任矣，卒至倾覆国家，故有此象。占者得此，败国杀身，凶可知矣。</p><h3 id="《象》曰-覆公餗-信如何也。" tabindex="-1">《象》曰：覆公餗，信如何也。 <a class="header-anchor" href="#《象》曰-覆公餗-信如何也。" aria-label="Permalink to “《象》曰：覆公餗，信如何也。”">​</a></h3><p>信者信任也，言以餗委托信任于人，今将餗覆之，则所信任之人为何如也。</p><p>六五，鼎黄耳，金铉，利贞。</p><p>五为鼎耳，黄中色，五居中，黄耳之象也。此爻变干金，金铉之象也。以此爻未变而言，则曰黄，以此爻既变而言，则曰金。在鼎之上，受铉以举鼎者耳也。在鼎之外，贯耳以举鼎者铉也。盖铉为鼎之系，系于其耳，二物不相离，故并言之。</p><p>六五有虚中之德，上比上九，下应九二，皆其刚明，故有黄耳金铉之象。鼎既黄耳金铉，则中之为实者，必美味矣。而占者则利于贞固也，因阴柔，故戒以此。</p><h3 id="《象》曰-鼎黄耳-中以为实也。" tabindex="-1">《象》曰：鼎黄耳，中以为实也。 <a class="header-anchor" href="#《象》曰-鼎黄耳-中以为实也。" aria-label="Permalink to “《象》曰：鼎黄耳，中以为实也。”">​</a></h3><p>黄中色，言中乃其实德也，故云黄耳。</p><p>上九，鼎玉铉，大吉，无不利。</p><p>上九居鼎之极，铉在鼎上，铉之象也。此爻变震，震为玉，玉铉之象也。玉岂可为铉，有此象也，亦如金车之意。鼎之为器，承鼎在足，实鼎在腹，行鼎在耳，举鼎在铉，鼎至于铉，厥功成矣。功成可以养人，亦犹井之元吉，大成也，故大吉无不利。</p><p>上九以阳居阴，刚而能柔，故有温润玉铉之象。占者得此，凡事大吉，而又行，无不利也。占者有玉铉之德，斯应是占矣。</p><h3 id="《象》曰-玉铉在上-刚柔节也。" tabindex="-1">《象》曰：玉铉在上，刚柔节也。 <a class="header-anchor" href="#《象》曰-玉铉在上-刚柔节也。" aria-label="Permalink to “《象》曰：玉铉在上，刚柔节也。”">​</a></h3><p>刚柔节者，言以阳居阴，刚而能节之以柔，亦如玉之温润矣，所以为玉铉也。</p>',38)])])}const f=e(l,[["render",h]]);export{_ as __pageData,f as default};
